export const ACSL_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/acsl-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAcslStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ACSL_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
